  _ = `Diese Einladung wurde zurückgezogen`,
  _ = `Wie funktionieren Einladungen?`,
  _ = `Sie werden per E-Mail benachrichtigt, wenn Ihr Spiel zur Teilnahme an einem Tagesangebot eingeladen wird. Ihr Spiel wird außerdem oben aufgeführt. Anschließend funktioniert der Prozess wie folgt:`,
  _ = `Wählen Sie für einen Zeitraum innerhalb der nächsten 6 Monate ein verfügbares und für Sie geeignetes Datum aus.`,
  _ = `Ihr Titel wird für 24 Stunden auf der Startseite von Steam und den entsprechenden Tag-Seiten hervorgehoben, während der Rabatt je nach ausgewählter Rabattdauer zwischen 7 und 14 Tagen aktiv ist. Dieser Zeitraum beginnt immer um 10:00 Uhr pazifischer Zeit Ihres ausgewählten Datums.`,
  _ = `Bei der Auswahl des Datums werden Sie aufgefordert, einen Prozentsatz für Ihren Rabatt einzugeben, und können Pakete zur Teilnahme an der Werbeaktion bestimmen.`,
  _ = `Bitte wählen Sie bei der Eingabe einen Prozentsatz, der Ihrem bisher höchsten Rabatt entspricht, oder einen noch höheren Rabatt.`,
  _ = `Wenn Sie jetzt noch nicht bereit sind, Ihr Tagesangebot zu planen, finden Sie die Einladung in Ihrem Dashboard für Tagesangebote. Bitte beachten Sie das Ablaufdatum.`,
  _ = `%1$s, falls Sie Ihr Datum ändern wollen, nicht mehr teilnehmen möchten oder weitere Fragen haben.`,
  _ = `Kontaktieren Sie uns hier`,
  _ = `Bewährte Praktiken für Tagesangebote`,
  _ = `Es ist oft von Vorteil, Ihre erhöhte Sichtbarkeit und Ihren Rabatt mit anderen Aktivitäten zu kombinieren, wie z. B. mit einem Inhaltsupdate, einem Livestream oder einem Communityevent.`,
  _ = `Wenn Sie innerhalb eines Monats nach Ihrem ausgewählten Tagesangebot andere Rabatte geplant haben, verwenden Sie bitte den gleichen Rabattprozentsatz für beide Rabatte. Ein Tagesangebot soll genauso gut oder besser als Ihre bisherigen Angebote sein.`,
  _ = `Weitere Informationen finden Sie in der Dokumentation zu <1>Tagesangeboten</1>`,
