  _ = `Einreichen bis %1$s.`,
  _ = `Ihre Demo muss die Build-Überprüfung durchlaufen, bevor Sie mit ihr an der Spielevorschau teilnehmen können. Diese Überprüfung stellt sicher, dass die Demo fehlerfrei läuft und die versprochenen Funktionen enthält; es handelt sich nicht um eine vollständige Qualitätskontrolle, daher sollten Sie Ihre Demo weiterhin selbst testen.`,
