  _ = `Anfrage zur Überprüfung:`,
  _ = `Marketingnachrichten zu einem großen Update erfordern eine Überprüfung von Valve, die Sie im Tab „Veröffentlichen“ des jeweiligen Updates über ein Ticket anfragen müssen. Dadurch wird sichergestellt, dass die Qualitätsmaßstäbe für eine Marketingnachricht erfüllt werden.`,
