  _ = `Aktionsseite`,
  _ = `Aktionsseite (Entwurf)`,
  _ = `Dieses Event ist zwar noch nicht sichtbar, jedoch zeigen wir Ihnen dies, weil eines Ihrer Spiele auf der Aktionsseite aufgeführt ist. Falls dies für Sie unerwartet ist, kontaktieren Sie bitte die Organisatoren der Aktion.`,
  _ = `So haben Sie abgeschnitten`,
  _ = `1 Ihrer Spiele hat teilgenommen.`,
  _ = `<1>%1$s</1> Ihrer Spiele haben teilgenommen.`,
  _ = `Für ein Spiel benötigen Sie die Berechtigung „%2$s“, um detaillierte Statistiken anzuzeigen.`,
  _ = `Für %1$s Spiele benötigen Sie die Berechtigung „%2$s“, um detaillierte Statistiken anzuzeigen.`,
  _ = `Vollständige Zusammenfassung anzeigen`,
  _ = `Wie ist die Spielevorschau für Sie verlaufen?`,
  _ = `Sie haben mit einem Spiel an der Spielevorschau teilgenommen.`,
  _ = `Sie haben mit <1>%1$s</1> Spielen an der Spielevorschau teilgenommen.`,
  _ = `Zur Anzeige detaillierter Statistiken benötigen Sie die Berechtigung „%1$s“.`,
  _ = `Sie verfügen nicht über die benötigten Rechte, um diese Statistik einzusehen.`,
  _ = `Finanzdaten einsehen`,
  _ = `Wie haben wir abgeschnitten? Bitte nehmen Sie an unserer kurzen Umfrage teil:`,
