  _ = `Dokumentation lesen`,
  _ = `In Deutschland angebotene Spiele erfordern ab dem 15. November 2024 Alterskennzeichen`,
  _ = `Einer Ihrer Anwendungen fehlt eine in Deutschland gültige Altersfreigabe. Diese wird deshalb ab dem 15.\xA0November\xA02024 Kunden in Deutschland nicht mehr im Steam-Shop angezeigt. Damit Sie Ihre Spiele weiterhin in Deutschland zum Kauf anbieten können, müssen Sie die Steam-Inhaltsbefragung beantworten und veröffentlichen.`,
  _ = `Mehreren Ihrer Anwendungen fehlt eine in Deutschland gültige Altersfreigabe. Diese werden deshalb ab dem 15.\xA0November\xA02024 Kunden in Deutschland nicht mehr im Steam-Shop angezeigt. Damit Sie Ihre Spiele weiterhin in Deutschland zum Kauf anbieten können, müssen Sie die Steam-Inhaltsbefragung beantworten und veröffentlichen.`,
  _ = `Verbleibende Anwendungen anzeigen`,
  _ = `Wichtige Aktionen`,
  _ = `Tagesangebot`,
  _ = `Sie haben eine Einladung erhalten, ein Tagesangebot zu planen.`,
  _ = `Sie haben eine Einladung zur Planung eines Tagesangebots erhalten, die in Kürze abläuft.`,
  _ = `E-Mail-Adressen`,
  _ = `Fügen Sie einen Kollegen oder sich selbst hinzu, um sicherzustellen, dass Sie wichtige E-Mails von Steam erhalten.`,
  _ = `Kein Nutzer Ihres Unternehmens erhält zurzeit Steamworks-Benachrichtigungen. Bitte erteilen Sie einem oder mehreren Nutzern mit einer gültigen E-Mail-Adresse die Berechtigung „Steamworks-Benachrichtigungen erhalten“, damit Sie über bevorstehende Aktionen, neue Funktionen oder besondere Einladungen informiert werden.`,
  _ = `Berechtigungen verwalten`,
  _ = `Adressanfrage`,
  _ = `Bitte geben Sie Ihre Postanschrift an`,
  _ = `Valve möchte Ihnen etwas zusenden. Bitte geben Sie bis zum %1$s Ihre Postanschrift an oder lehnen Sie die Zusendung ab.`,
  _ = `Valve möchte Ihnen etwas zusenden. Diese Anfrage war bis zum %1$s fällig. Sie können uns jedoch weiterhin eine Postanschrift übermitteln oder die Zusendung ablehnen.`,
  _ = `Valve möchte Ihnen etwas zusenden. Bitte geben Sie Ihre Postanschrift an oder lehnen Sie die Zusendung ab.`,
  _ = `Adresse eingeben`,
  _ = `Postanschrift`,
  _ = `Die Angabe ermöglicht es uns, Ihnen physische Artikel zuzusenden und optimale Veranstaltungsorte für zukünftige Steamworks-Events zu finden.`,
  _ = `Die Anschrift kann von der bei Ihrer Steamworks-Anmeldung angegebenen Adresse abweichen. Falls Ihr Unternehmen über mehrere Postanschriften für einen einzigen Steamworks-Account verfügt, geben Sie bitte jede einzelne Adresse an.`,
  _ = `Neue Adresse hinzufügen`,
  _ = `Telefonnummer`,
  _ = `Durch Hinzufügen einer SMS-fähigen Telefonnummer erhöhen Sie die Sicherheit Ihres Steamworks-Partneraccounts um eine weitere Stufe.`,
  _ = `Telefonnummer hinzufügen`,
  _ = `Bankinformationen laufen in Kürze ab`,
  _ = `Bitte aktualisieren Sie Ihre Bankinformationen bis zum folgenden Datum oder wir können keine Zahlungen mehr an Sie durchführen: %1$s.`,
  _ = `Für die in Ihrem Account aufgeführten Bankdaten wurden seit über 12 Monaten keine Zahlungsaktivitäten verbucht. Aus diesem Grund werden diese am %1$s automatisch deaktiviert.<br><br>Wenn Sie die Bankdaten nicht bestätigen, werden diese am Ablaufdatum deaktiviert und wir können Ihnen kein Geld mehr überweisen.`,
  _ = `Verifizieren oder aktualisieren`,
