  _ = `Frist für Elementanfragen`,
  _ = `Nehmen Sie die Einladung bis zum %1$s an, um diese Gelegenheit nicht zu verpassen.`,
  _ = `Nehmen Sie für einen planmäßigen Ablauf diese Einladung bis zum %1$s an`,
  _ = `Ihre Steuerangaben erfordern Aufmerksamkeit`,
  _ = `Wichtige steuerrechtliche Angaben zu Ihrer Überprüfung`,
