  _ = `Sie haben eine Nachricht zu Ihrem Steuerstatus erhalten`,
  _ = `Ihre Steuerunterlagen/Datei zur Identitätsüberprüfung sind/ist eingegangen.`,
  _ = `Zum Abschluss Ihrer KYC-Verifizierung sind zusätzliche Dokumente erforderlich.`,
  _ = `Zum Abschluss Ihrer Verifizierung sind zusätzliche Dokumente erforderlich.`,
  _ = `Ihre steuerrechtlichen Angaben sind abgelaufen.`,
  _ = `Ihre steuerrechtlichen Angaben sind ungültig.`,
  _ = `Möglicherweise haben Sie Anspruch auf Steuervergünstigungen aufgrund eines Steuerabkommens.`,
  _ = `Publisher-Berechtigungen für die Vertretungsmacht erfordern Ihre Handlung.`,
  _ = `Neue Steuerunterlagen sind verfügbar.`,
  _ = `Die Pressevorschau beginnt`,
  _ = `Mitglieder der Presse haben Zugriff auf eine Vorschau der Hauptseite der Spielevorschau und auf die Teilnehmer. Wenn Ihre Demo bereits live geschaltet ist, können sie außerdem Ihre Demo spielen.`,
  _ = `Einreichungsfrist für Demo-Build`,
  _ = `Ihr Demo-Build muss noch überprüft werden. Reichen Sie den Build bis zu diesem Datum ein, damit vor Beginn der Steam-Spielevorschau genügend Zeit für die Überprüfung bleibt. <1>Erfahren Sie hier mehr über das Prüfverfahren.</1>`,
