  _ = `Um Bilder in den Editor einzufügen, müssen diese zunächst im Abschnitt „Eigene Bilder hochladen“ hochgeladen werden. Bewegen Sie den Mauszeiger über das hochgeladene Bild und klicken Sie dann über %1$s auf die Schaltfläche „Bildname in die Zwischenablage kopieren“. Fügen Sie dann den Namen innerhalb des Codes [img][/img] wie folgt in das Beschreibungsfeld ein:`,
