  _ = `Dieses Bild wurde hochgeladen, bevor lokalisierte Bildgruppen unterstützt wurden. Bitte laden Sie es erneut hoch, um eine neue lokalisierte Bildgruppe zu erstellen oder Alternativtext hinzuzufügen.`,
