  _ = `Beim Hochladen ist ein Fehler aufgetreten: „%1$s“`,
  _ = `Es scheint, als wäre das Dokument erfolgreich hochgeladen worden, jedoch konnte es nicht bearbeitet werden. Bitte versuchen Sie, das Bild über die Werkzeugleiste einzufügen.`,
  _ = `Ihre benutzerdefinierten Bilder:`,
