  _ = `Wählen Sie einen Zusatzinhalt aus, der auf Ihrer Shopseite angezeigt werden soll`,
  _ = `Anti-Cheat`,
  _ = `Wenn Ihr Spiel eine clientseitige Anti-Cheat-Lösung auf Kernel-Ebene installiert, müssen Sie Nutzer darüber hier aufklären. Falls Sie eine eigene oder eine unten nicht aufgeführte Anti-Cheat-Lösung verwenden, wählen Sie bitte „Andere“ aus und geben Sie Ihre eigenen Informationen ein.`,
  _ = `Wenn Ihr Spiel von einem client- oder serverbasierten Anti-Cheat-Schutz Gebrauch macht, der nicht kernelbasiert ist, sind die Angaben in diesem Bereich optional. Grundsätzlich ist es jedoch für jedes Spiel mit Anti-Cheat-Technologie von Vorteil, Spieler darüber zu informieren.`,
  _ = `Anti-Cheat-Werkzeug:`,
  _ = `Integration auf Kernel-Ebene`,
  _ = `Diese Anti-Cheat-Lösung erfordert die Installation oder Änderung von Dateien auf der Ebene des Betriebssystemkernels.`,
  _ = `Diese Anti-Cheat-Lösung ändert keine Dateien auf der Ebene des Betriebssystemkernels.`,
  _ = `Bitte auswählen, falls Ihre Anti-Cheat-Lösung für einen beliebigen Modus Ihres Spiels Dateien auf der Ebene des Betriebssystemkernels installiert.`,
  _ = `Deinstalliert sich vollständig`,
  _ = `Wählen Sie diese Option nur aus, wenn Sie bestätigen können, dass sämtliche für Ihr Spiel installierten Anti-Cheat-bezogenen Dateien bei der Deinstallation des Spiels vom Datenträger entfernt werden.`,
  _ = `Erfordert Sicheren Start`,
  _ = `Falls Ihr Spiel Sicherer Start, TPM oder andere Schutzvorkehrungen beim Starten des Geräts in beliebigen Spielemodi erfordert, wählen Sie bitte die erforderliche Kombination.`,
  _ = `Keine Auswahl`,
