  _ = `PunkBuster`,
  _ = `VAC (Valve Anti-Cheat)`,
  _ = `nProtect GameGuard`,
  _ = `HackShield`,
  _ = `Anti-Cheat Expert (ACE)`,
  _ = `SARD Anti-Cheat`,
  _ = `HProtect`,
  _ = `Andere`,
  _ = `Alle Plattformen`,
  _ = `Windows`,
  _ = `Markieren Sie dieses Kästchen, wenn keine Redistributables benötigt werden`,
  _ = `Unreal Engine benötigt in der Regel Visual C++. Einige UE-Spiele erfordern ggf. auch DirectX.`,
  _ = `Editionen gruppieren`,
  _ = `Beschreiben Sie Ihre Editionen ...`,
  _ = `Mithilfe dieser Schnittstelle können Sie ein Bild bereitstellen, das die Unterschiede zwischen den Editionen Ihres Spiels beschreibt (z.\xA0B. Standard, Deluxe, Spiel des Jahres usw.). Die Editionen werden mit dem Basisspiel in den Kaufoptionen oben gruppiert und auf der Shop-Seite vom niedrigsten zum höchsten Preis sortiert. Weitere Informationen finden Sie in der Dokumentation zu <1>Editionen beschreiben</1>.`,
  _ = `Gruppieren Sie verschiedene Editionen Ihres Titels (Gold, Deluxe usw.) und stellen Sie diese in einer optionalen Vergleichsgrafik dar.`,
  _ = `(%1$s als Editionen ausgewählt)`,
  _ = `Keine Vergleichsgrafik hochgeladen`,
  _ = `Vergleichsgrafik hochgeladen`,
