  _ = `Beginnen Sie mit der Eingabe, um die Liste Ihrer Pakete zu filtern.`,
  _ = `Wählen Sie aus, welche Pakete Editionen sind (z. B. Standard, Gold, Deluxe, Spiel des Jahres usw.).`,
  _ = `Speichern`,
  _ = `Abbrechen`,
  _ = `Klicken Sie hier oder ziehen Sie ein Bild per Drag-and-drop hierher, um es hochzuladen.`,
  _ = `Löschen`,
  _ = `Klicken Sie hier oder ziehen Sie ein Bild per Drag-and-Drop hierher, um das aktuelle zu ersetzen.`,
  _ = `Laden Sie ein Bild hoch (%1$s x %2$s Pixel), in dem die beiden ausgewählten Editionen im Vergleich zu sehen sind. Dieses Bild wird in einem Dialog angezeigt, wenn ein Nutzer auf der Shop-Seite Ihrer Anwendung auf „Editionen vergleichen“ klickt. Verwenden Sie das Dropdown-Menü, um lokalisierte Versionen Ihres Bildes hochzuladen.`,
  _ = `Nachdem Sie Ihre Änderungen gespeichert haben, müssen Sie diese <1>veröffentlichen</1>, um sie für Nutzer sichtbar zu machen.`,
  _ = `Vergessen Sie nicht, Ihre Änderungen zu <1>veröffentlichen</1>.`,
  _ = `Bilder zum Vergleich Ihrer Editionen müssen %1$s × %2$s Pixel groß sein. Das hochgeladene Bild war %3$s × %4$s.`,
  _ = `Editionen müssen das Basisspiel (%1$s, Paket-ID %2$s) enthalten.`,
  _ = `Die Bilder für folgende Sprachen haben die falsche Größe: %1$s`,
  _ = `Änderungen an den Editionen werden gespeichert\xA0…`,
  _ = `Gespeichert`,
  _ = `OK`,
  _ = `Änderungen werden gespeichert\xA0…`,
  _ = `Geben Sie einen Alternativtext ein, der von Bildschirmlesern zur Beschreibung des Bildes verwendet wird. Schreiben Sie den Text so, als würden Sie einem Nutzer den Unterschied zwischen Ihren Editionen erklären.`,
  _ = `Richtlinien für grafische Elemente`,
  _ = `Bevor Sie fortfahren, stellen Sie bitte sicher, dass Ihre Bilder unseren Richtlinien entsprechen. Sollte dies während unserer Überprüfung nicht der Fall sein, müssen Sie die Bilder korrigieren, damit der Prozess fortgesetzt werden kann. Weitere Informationen finden Sie in unserer Dokumentation zu den <1>Richtlinien für grafische Elemente</1>.`,
  _ = `Bestätigen und hochladen`,
  _ = `Ich bestätige, dass diese Kapsel ein gut lesbares Logo enthält, das die Bildgröße weitestgehend ausfüllt.`,
  _ = `Ich bestätige, dass diese Kapsel außer dem Logo keinen zusätzlichen Text enthält.`,
