  _ = `Klicken Sie auf „%1$s“, um eine Beschreibung für einen Paketinhalt ohne App-ID hinzuzufügen.`,
  _ = `Auf der Shopseite sichtbar`,
  _ = `Kaufanzeige des Pakets`,
  _ = `Kapselbild der Anwendungen im Kaufbereich dieses Pakets anzeigen.`,
  _ = `(Bearbeiten Sie die Liste von Kapselbildern, die für dieses Paket angezeigt werden sollen, auf der Seite „Shoppaket bearbeiten“.)`,
  _ = `Mit dieser Option werden der Kaufanzeige des Pakets im Shop Kapselbilder hinzugefügt, ähnlich wie bei der Anzeige von Bündeln. Die Basisanwendung wird an erster Stelle angezeigt, gefolgt von allen weiteren enthaltenen Anwendungen (absteigend nach Preis sortiert).`,
  _ = `Spielnamen am Anfang der Listeneinträge von Paketinhalten auslassen`,
  _ = `Zur Vermeidung von Redundanz und Verbesserung der Lesbarkeit können der Spielname (inkl. Leerzeichen) und Trennzeichen (z.\xA0B. Doppelpunkte, Bindestriche usw.) am Anfang der im Kaufbereich des Pakets aufgeführten Inhalte (z.\xA0B. Zusatzinhalte, Soundtracks usw.) ausgelassen werden. So wird beispielsweise Half-Life: Episode 1 als Episode 1 angezeigt. Nur der genaue Name des Basisspiels, Leerzeichen und Trennzeichen werden nicht angezeigt.`,
  _ = `Speichern und veröffentlichen`,
  _ = `Abbrechen`,
  _ = `Angesagtes Event zum großen Update`,
  _ = `Besitzer des Spiels werden in ihrer Bibliothek zum Event weitergeleitet, um mehr Kontext zu erhalten. Wir suchen nach Events, die mit dem Basisspiel verknüpft sind.`,
  _ = `[Sichtbar am %1$s] Eventname: %2$s`,
  _ = `[Entwurf] Eventname: %2$s`,
  _ = `[Gestartet am %1$s] Eventname: %2$s`,
  _ = `Kein passendes Event gefunden. Erfordert einen Entwurf oder einen innerhalb des letzten Monats veröffentlichten Beitrag. <1>Siehe Dashboard zu „Events und Ankündigungen“</1>`,
  _ = `Die Positionierung Ihres Logos wurde gespeichert. Sie können diese Änderungen nun über die Shopseitenverwaltung veröffentlichen.`,
  _ = `Verwaltung von Rabatten`,
  _ = `Aktionstermine können sich jederzeit ändern. Gehen Sie daher mit Bedacht bei der öffentlichen Bekanntgabe von Terminen vor, vor allem bei Events, die weit in der Zukunft liegen.`,
  _ = `Hinweise`,
  _ = `Hinweis: Sie können keinen Rabatt innerhalb von 30 Tagen nach folgenden Handlungen einreichen: die Erstveröffentlichung eines Spiels zum Vollpreis ODER eine Preiserhöhung in einer beliebigen Währung. Mehr dazu erfahren Sie hier: %1$s.`,
  _ = `Dokumentation`,
  _ = `Rabattaktionen beginnen und enden um 18 oder 19\xA0Uhr\xA0ME(S)Z, falls nicht anders angegeben.`,
  _ = `Benutzerdefinierter Rabatt`,
  _ = `Rabatt erstellen …`,
  _ = `+ Neu erstellen`,
  _ = `Erstellen Sie einen benutzerdefinierten Rabatt oder aktivieren Sie ein Wochenangebot, an dem Ihre Spiele teilnehmen.`,
  _ = `Rabatte importieren/exportieren`,
  _ = `Werkzeuge`,
  _ = `CSV-Datei importieren/exportieren …`,
  _ = `Die Kalkulation von Rabatten für Ihre Spielpakete kann auch über Änderungen an einer CSV-Datei verwaltet werden. Dies ist ggf. nützlich, wenn Sie überprüfen wollen, ob Ihre Rabatte für eine Reihe von Titeln konsistent sind, oder Sie eine Vielzahl von Rabatten auf einmal aktualisieren wollen.`,
  _ = `Laden Sie Ihre Tabelle mit Rabatten vom Dashboard als CSV-Datei herunter. Diese Tabelle enthält ausstehende Änderungen, die noch nicht gespeichert wurden.`,
  _ = `Alle herunterladen`,
  _ = `Laden Sie die Rabatte für alle Pakete herunter.`,
  _ = `Sichtbare Rabatte herunterladen`,
  _ = `Laden Sie die Rabatte für alle sichtbaren Pakete herunter, mit Ausnahme derer, die Sie durch Eingabe eines Textfilters oder Zuklappen einer Reihe versteckt haben.`,
  _ = `Laden Sie eine CSV-Datei mit einer aktualisierten Rabatttabelle hoch. Jegliche Einträge, die nicht mit den aktuellen Rabatten übereinstimmen, werden im Dashboard als ausstehende Änderungen eingegeben. Sie können sich vor der Einreichung eine Vorschau dieser Rabatte ansehen.`,
