  _ = `Registrierung bearbeiten`,
  _ = `Registrierung anzeigen`,
  _ = `Registrieren Sie Ihren Titel`,
  _ = `Klicken Sie auf die Schaltfläche unten, um Ihr Interesse an diesem Event zu bekunden und die Möglichkeit zur Eingabe von Rabatten freizuschalten. Sobald das Startdatum näherrückt, können wir Ihnen so wichtige Informationen zu diesem Event mitteilen. Sie können Ihren Titel jederzeit wieder abmelden.`,
  _ = `Konflikt`,
  _ = `Ein Paket wurde innerhalb von %1$s\xA0Tagen nach diesem Rabatt veröffentlicht.`,
  _ = `Ein Spiel in diesem Paket hat den Preis in mindestens einer Währung innerhalb von %1$s\xA0Tagen nach diesem Rabatt erhöht.`,
  _ = `Für dieses Paket ist bereits ein Rabatt innerhalb von %1$s\xA0Tagen vor/nach diesem Rabatt eingeplant.`,
  _ = `Für dieses Paket ist bereits ein Rabatt in diesem Zeitraum eingeplant.`,
  _ = `AUSSTEHENDE RABATTE SPEICHERN?`,
  _ = `Speichern der Änderungen aktualisiert %1$s Rabatte und legt %2$s neue fest.`,
  _ = `Speichern der Änderungen aktualisiert einen (1) Rabatt. `,
  _ = `Speichern der Änderungen aktualisiert %1$s Rabatte.`,
  _ = `Speichern der Änderungen legt einen (1) neuen Rabatt fest.`,
  _ = `Speichern der Änderungen legt %1$s neue Rabatte fest.`,
  _ = `FEHLER: Serverausfall. Bitte versuchen Sie es in Kürze erneut.`,
  _ = `Der Rabatt kann nicht weniger als 10 % betragen.`,
  _ = `Einige Pakete erfordern einen geringeren Rabatt, da der Mindestpreis in mindestens einer Währung bzw. Region nicht unter dem Äquivalent von 0,49\xA0US-Dollar liegen darf.`,
  _ = `Sie können für dieses Paket keinen Rabatt über %1$s\xA0% festlegen, da der Mindestpreis in mindestens einer Währung bzw. Region nicht unter dem Äquivalent von 0,49\xA0US-Dollar liegen darf.`,
  _ = `Der Grundpreis dieses Paketes liegt für eine oder mehrere Währungen unter dem zulässigen Mindestpreis. Deshalb können Sie keinen Rabatt für dieses Paket eingeben.`,
  _ = `Pakete, die mit diesem Symbol markiert sind, werden zu einem bereits gewährten Rabatt hinzugefügt. Nach dem Speichern ist das eingegebene Angebot sofort gültig.`,
  _ = `Der geplante Rabatt führt dazu, dass der Preis dieses Pakets in einer oder mehreren Währungen unter den zulässigen Mindestpreis fällt. Deshalb kann dieses Paket in diesen Ländern nicht erworben werden. Um sicherzustellen, dass dieses Paket überall erhältlich ist, sollte der Rabatt für dieses Paket kleiner als %1$s% Prozent sein.`,
  _ = `Der Grundpreis dieses Pakets liegt für eine oder mehrere Währungen unter dem zulässigen Mindestpreis. Daher ist dieses Paket nicht in diesen Ländern erhältlich. Dies gilt auch für Länder, in denen Ihr Rabatt dazu führt, dass der Preis unter den zulässigen Mindestbetrag fällt. Um sicherzustellen, dass dieses Paket überall erworben werden kann, aktualisieren Sie bitte die Preise für dieses Paket auf den Steam-Mindestpreis.`,
  _ = `Sie haben eine (1) ungespeicherte Änderung an den Rabatten. Wenn Sie diese verwerfen, werden alle neuen Rabatte aufgehoben und aktualisierte Rabatte auf ihren vorherigen Stand zurückgesetzt.`,
  _ = `Sie haben eine %1$s ungespeicherte Änderungen an den Rabatten. Wenn Sie diese verwerfen, werden alle neuen Rabatte aufgehoben und aktualisierte Rabatte auf ihren vorherigen Stand zurückgesetzt.`,
  _ = `Anwendungsstartseite aufrufen`,
  _ = `EVENT-DETAILS`,
  _ = `IHRE ANSICHT DIESES EVENTS`,
  _ = `Beginnt: %1$s`,
  _ = `Endet: %1$s`,
  _ = `Aktuell werden %1$s von %2$s möglichen Paketen angezeigt.`,
  _ = `Pakete mit Konflikten ausblenden.`,
  _ = `Sie können anhand des Paketnamens filtern oder die Spielbereiche links zusammenklappen.`,
  _ = `ALLE SICHTBAREN PAKETE RABATTIEREN`,
  _ = `Geben Sie einen Rabatt zwischen 10\xA0% und 95\xA0% an.`,
  _ = `Sie können auch den Wert 0 eingeben, um die Rabatte von allen sichtbaren Paketen zu entfernen.`,
  _ = `Damit legen Sie für alle sichtbaren Pakete einen Rabatt fest. Bestehende Rabatte werden somit überschrieben. Dies ist dasselbe, als würden Sie den Wert in jedem Eingabefeld separat eingeben. Sie können alle Rabatte überprüfen und bestätigen, bevor diese angewendet werden.`,
  _ = `HINWEIS: Der Rabatt von mindestens einem dieser Pakete kann nur bis zu %1$s\xA0% betragen.`,
  _ = `Weitere Informationen`,
  _ = `AUF EIN PAKET ANWENDEN`,
  _ = `AUF %1$s PAKETE ANWENDEN`,
  _ = `All Events anzeigen`,
  _ = `Eine Vorschau Ihres Preises basierend auf dem von Ihnen eingegebenen Rabattprozentsatz.`,
  _ = `BETA`,
