  _ = `SPEICHERN & WEITER?`,
  _ = `Ihre ausstehenden Änderungen sind noch nicht gespeichert. Möchten Sie diese speichern, bevor Sie die Seite verlassen?`,
  _ = `Kein Spiel im Paket`,
  _ = `Diese Pakete enthalten entweder Zusatzinhalte, bei denen ein Link zum Hauptspiel fehlt, oder Spiel-fremde Anwendungen wie ein Video.`,
