  _ = `Startseite des Pakets aufrufen`,
  _ = `Die Preise dieses Pakets für eine oder mehrere Währungen liegen unter dem zulässigen Mindestpreis. Scrollen Sie nach rechts, um spezifische Währungen mit Warnungen zu sehen.`,
  _ = `Dieses Paket verfügt über einen oder mehrere geplante Rabatte, die den Preis des Spiels für eine oder mehrere Währungen unter dem zulässigen Mindestpreis drücken. Scrollen Sie nach rechts, um spezifische Warnungen zu sehen.`,
