  _ = `Dokumentation`,
  _ = `Kontaktieren Sie uns`,
  _ = `Preise umrechnen\xA0…`,
  _ = `Klicken Sie auf diese Schaltfläche, um Ihren Preis auf Basis Ihres US-Dollarpreises schnell in alle Währungen umzurechnen. Sie können die Preisänderungen vor dem Absenden überprüfen.`,
  _ = `Basierend auf dem US-Dollarpreis umrechnen`,
  _ = `Ihre angegebenen Preise stimmen bereits mit denen der ausgewählten Umrechnungsmethode überein.`,
  _ = `Preisempfehlungen`,
  _ = `Um Ihnen die Preisgestaltung in den über 35 von Steam unterstützten Währungen zu erleichtern, bietet dieses Werkzeug eine Umrechnungsmethode, mit der Sie Ihren Basispreis in US-Dollar in einen für andere Regionen geeigneten Preis umrechnen können. Diese Umrechnung basiert auf einer Kombination aus Währungswert, regionaler Kaufkraft, anfallenden Steuern und unserer eigenen Verkaufserfahrung in den jeweiligen Regionen.`,
  _ = `Durch Klicken auf die untere Schaltfläche werden die umgerechneten Preise für alle sichtbaren Pakete übernommen, mit Ausnahme derer, die Sie durch Eingabe eines Textfilters oder durch das Zuklappen einer Reihe versteckt haben.`,
  _ = `Erfahren Sie mehr über Steams regionale Preisgestaltung.`,
  _ = `Jegliche Änderungen können vor Veröffentlichung von Ihnen überprüft und bestätigt werden.`,
