  _ = `Ausgeblendet`,
  _ = `Spoiler`,
  _ = `Um Spoiler aus dem Spiel zu vermeiden, wird die Errungenschaft erst angezeigt, wenn der Nutzer mit der Maus darüberfährt.`,
  _ = `Sichtbar`,
  _ = `Archiviert`,
  _ = `Die Errungenschaft bleibt für Nutzer sichtbar, die sie bereits freigeschaltet haben, kann aber nicht mehr freigeschaltet werden.`,
  _ = `Verfügbar`,
  _ = `Ausgelöst durch`,
  _ = `Fortschrittsstatistik`,
  _ = `Verwenden Sie eine Statistik, um den Fortschritt zum Erreichen der Errungenschaft anzuzeigen`,
  _ = `Sichtbarkeit`,
  _ = `Optionaler Status`,
  _ = `Min.`,
